sys_script_include.script:
var WF_NonMajorIncidentUtil = Class.create();
WF_NonMajorIncidentUtil.prototype = {
    initialize: function() {},

	createKBarticle: function(sysid, tgtSysid) {
        var knowledge = new GlideRecord("m2m_kb_task");
        knowledge.addQuery("task", sysid);
        knowledge.query();
        while (knowledge.next()) {
            var addArticle = new GlideRecord('m2m_kb_task');
            addArticle.initialize();
            addArticle.task = tgtSysid;
            addArticle.kb_knowledge = knowledge.kb_knowledge;
            addArticle.insert();
        }
    },

    type: 'WF_NonMajorIncidentUtil'
};
